const input = $input.first()?.json ?? {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const clean = (value, max) => String(value ?? '').replace(/[\r\n\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);
const email = clean(body.email, 254);
const contactName = clean(body.contactName, 120);
const company = clean(body.company, 160);
const base64 = String(body.pdfBase64 ?? '');

if (clean(body.website, 200)) throw new Error('Solicitud no válida.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Correo no válido.');
if (!contactName || !company) throw new Error('Faltan datos de contacto.');
if (!base64 || base64.length > 7_000_000 || base64.length % 4 !== 0 || !/^[A-Za-z0-9+/]+={0,2}$/.test(base64)) {
  throw new Error('Adjunto PDF no válido.');
}
const pdf = Buffer.from(base64, 'base64');
if (pdf.length < 100 || pdf.length > 5 * 1024 * 1024 || pdf.subarray(0, 5).toString() !== '%PDF-') {
  throw new Error('Adjunto PDF no válido.');
}
const attachment = await this.helpers.prepareBinaryData(
  pdf,
  'Propuesta_Outsourcing_Grupo_Empodera.pdf',
  'application/pdf',
);
return [{
  json: {
    email,
    subject: 'Tu propuesta preliminar de Outsourcing | Grupo Empodera',
    message: `Hola ${contactName},\n\nAdjuntamos la propuesta preliminar de Outsourcing para ${company}. La estimación se basa en la información que compartiste y los conceptos sujetos a revisión están indicados en el documento.\n\nSaludos,\nGrupo Empodera`,
  },
  binary: { attachment },
}];

